from functools import lru_cache

@lru_cache(maxsize=None)
def m(x, y):
    # x: remaining capacity, y: remaining items
    # returns max total value with constraints
    if x == 0 or y == 0:
        return 0
    i = y - 1  # index of last item
    wi, vi = items[i]
    if wi > x:
        return m(x, y-1)
    return max(m(x, y-1), vi + m(x-wi, y-1))

